(5445030, 783816, 15711, '<td valign="top">GREAT title.  That is totally creepy.  YIKES</td>', 'GREAT title.  That is totally creepy.  YIKES', '2009-04-20 09:42:41.000000', NULL, 1),
(5445032, 783961, 15711, '<td valign="top">God, you are going to give me bad dreams for sure.</td>', 'God, you are going to give me bad dreams for sure.', '2009-04-20 09:42:57.000000', NULL, 1),
