(5445063, 783932, 54645, '<td valign="top">I like the concept.</td>', 'I like the concept.', '2009-04-20 10:05:01.000000', NULL, 1),
(5445069, 783576, 58457, '<td valign="top">Is the drink drugged?  I''m pretty sure that''s what you are going for, but its slightly ambiguous.  maybe if it included a man''s hand in the image or something.  not sure.  Certainly a nightmare though.</td>', 'Is the drink drugged?  I''m pretty sure that''s what you are going for, but its slightly ambiguous.  maybe if it included a man''s hand in the image or something.  not sure.  Certainly a nightmare though.', '2009-04-20 10:06:08.000000', NULL, 1),
