(5445972, 783647, 36141, '<td valign="top">You have some scary spiders overthere. Normally I love spiders, but then we don''t have poisened ones where I live.</td>', 'You have some scary spiders overthere. Normally I love spiders, but then we don''t have poisened ones where I live.', '2009-04-20 20:10:09.000000', NULL, 1),
(5445981, 782539, 36141, '<td valign="top">The light is out for me. Such a beautiful picture otherwise, but I guess it came with the glass? The whole has a beautiful Art Deco look.</td>', 'The light is out for me. Such a beautiful picture otherwise, but I guess it came with the glass? The whole has a beautiful Art Deco look.', '2009-04-20 20:17:45.000000', NULL, 1),
(5445983, 783843, 36141, '<td valign="top">LOL did they blow up your dentist? Very nice take, love the colors.</td>', 'LOL did they blow up your dentist? Very nice take, love the colors.', '2009-04-20 20:19:09.000000', NULL, 1),
(5445984, 783863, 36141, '<td valign="top">Did it all come off afterwards? Nice take.</td>', 'Did it all come off afterwards? Nice take.', '2009-04-20 20:21:00.000000', NULL, 1),
(5445985, 783956, 36141, '<td valign="top">Yes, that''s the nightmare of most parents. Nice colors.</td>', 'Yes, that''s the nightmare of most parents. Nice colors.', '2009-04-20 20:22:05.000000', NULL, 1),
(5446004, 783965, 101256, '<td valign="top">Not so much a nightmare as it is laugh out loud funny. A great image and not so scary or nightmarish. It would appear that the horse is having a bit of fun with the author. A great image.</td>', 'Not so much a nightmare as it is laugh out loud funny. A great image and not so scary or nightmarish. It would appear that the horse is having a bit of fun with the author. A great image.', '2009-04-20 20:43:57.000000', NULL, 1),
(5446005, 783809, 101256, '<td valign="top">Without ever seeing the movie, it would be hard to comment on how this reflects as a "nightmare". As a straight image, it''s a good one with the right on the edge whites and somewhat vauge headlight area. A very compelling image.</td>', 'Without ever seeing the movie, it would be hard to comment on how this reflects as a "nightmare". As a straight image, it''s a good one with the right on the edge whites and somewhat vauge headlight area. A very compelling image.', '2009-04-20 20:45:54.000000', NULL, 1),
(5446006, 783961, 102315, '<td valign="top">I love this. Looks like a movie poster. Good processing and love the color.</td>', 'I love this. Looks like a movie poster. Good processing and love the color.', '2009-04-20 20:46:52.000000', NULL, 1),
(5446008, 783075, 99140, '<td valign="top">Compelling pic and definately very dreamlike</td>', 'Compelling pic and definately very dreamlike', '2009-04-20 20:47:27.000000', NULL, 1),
(5446010, 782618, 99140, '<td valign="top">Reminds me of the killer bunny in Monty Pythons Holy Grail movie - he is just too cute to be a nightmare!</td>', 'Reminds me of the killer bunny in Monty Pythons Holy Grail movie - he is just too cute to be a nightmare!', '2009-04-20 20:48:37.000000', NULL, 1),
(5446014, 782411, 99140, '<td valign="top">This is one of my reoccuring nightmares. Holds the essence of the nightmare for me</td>', 'This is one of my reoccuring nightmares. Holds the essence of the nightmare for me', '2009-04-20 20:49:55.000000', NULL, 1),
(5446016, 782475, 102315, '<td valign="top">Seems like a stretch to meet the challenge. Sorry</td>', 'Seems like a stretch to meet the challenge. Sorry', '2009-04-20 20:51:46.000000', NULL, 1),
(5446017, 782475, 99140, '<td valign="top">Great shot - those teeth look ferocious and they have got those crazy eyes!</td>', 'Great shot - those teeth look ferocious and they have got those crazy eyes!', '2009-04-20 20:51:49.000000', NULL, 1),
(5446019, 783555, 102315, '<td valign="top">I do like the effect of the picture but I don''t get it. What is your worst nightmare?</td>', 'I do like the effect of the picture but I don''t get it. What is your worst nightmare?', '2009-04-20 20:53:09.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5446020, 783854, 102315, '<td valign="top">Very cool effect!</td>', 'Very cool effect!', '2009-04-20 20:53:38.000000', NULL, 1),
(5446022, 783548, 102315, '<td valign="top">I really like the technical''s of this photo.</td>', 'I really like the technical''s of this photo.', '2009-04-20 20:55:18.000000', NULL, 1),
(5446025, 782258, 102315, '<td valign="top">I think this shot would have been better with a person lying in the sand. Great colors.</td>', 'I think this shot would have been better with a person lying in the sand. Great colors.', '2009-04-20 20:57:26.000000', NULL, 1),
(5446026, 783874, 99140, '<td valign="top">Would not want to run into him in a dark alley - at least in this context with that knife</td>', 'Would not want to run into him in a dark alley - at least in this context with that knife', '2009-04-20 20:57:42.000000', NULL, 1),
(5446029, 783765, 102315, '<td valign="top">This photo is very scary. Great idea, looks really sharp!</td>', 'This photo is very scary. Great idea, looks really sharp!', '2009-04-20 20:58:18.000000', NULL, 1),
(5446034, 783594, 102315, '<td valign="top">Without the picture on the TV I would have thought that you were stretching to make a photo for this challenge. Great idea and good thought was put into this one.</td>', 'Without the picture on the TV I would have thought that you were stretching to make a photo for this challenge. Great idea and good thought was put into this one.', '2009-04-20 21:00:05.000000', NULL, 1),
(5446037, 781977, 102315, '<td valign="top">I don''t know if this is what you were going for but this reminds me of when I used to have arguments with my dad about why I wanted to keep my hair long. He didn''t understand.</td>', 'I don''t know if this is what you were going for but this reminds me of when I used to have arguments with my dad about why I wanted to keep my hair long. He didn''t understand.', '2009-04-20 21:02:03.000000', NULL, 1),
(5446039, 783816, 102315, '<td valign="top">That''s a fairly realistic looking eye. Very cool. Is that a glass eye?</td>', 'That''s a fairly realistic looking eye. Very cool. Is that a glass eye?', '2009-04-20 21:03:00.000000', NULL, 1),
(5446040, 782942, 99140, '<td valign="top">Well the decapitated devil is eerie - interesting portrayal</td>', 'Well the decapitated devil is eerie - interesting portrayal', '2009-04-20 21:03:07.000000', NULL, 1),
(5446043, 783882, 102315, '<td valign="top">Looks similar to one that was in the first nightmare challenge but I think this one was done great. The King on the stone makes me immediately think of Stephen King also. Black and white really makes this pop. 9</td>', 'Looks similar to one that was in the first nightmare challenge but I think this one was done great. The King on the stone makes me immediately think of Stephen King also. Black and white really makes this pop. 9', '2009-04-20 21:04:26.000000', NULL, 1),
(5446045, 783075, 102315, '<td valign="top">Seems like an image you might find in a Marilyn Manson CD booklet. Very creepy.</td>', 'Seems like an image you might find in a Marilyn Manson CD booklet. Very creepy.', '2009-04-20 21:05:29.000000', NULL, 1),
(5446048, 783576, 102315, '<td valign="top">I think this will be too subtle for the quick voters to notice the pill in the drink. Good concept but could also use better lighting.</td>', 'I think this will be too subtle for the quick voters to notice the pill in the drink. Good concept but could also use better lighting.', '2009-04-20 21:07:56.000000', NULL, 1),
(5446053, 783963, 99140, '<td valign="top">I can see the nightmare in this for people who hate snakes especially around the face but it seems too bright to me and I would have possibly liked to see the snakes face/head.</td>', 'I can see the nightmare in this for people who hate snakes especially around the face but it seems too bright to me and I would have possibly liked to see the snakes face/head.', '2009-04-20 21:08:53.000000', NULL, 1),
(5446054, 783869, 102315, '<td valign="top">Not a particularly interesting subject and too over processed for my liking.</td>', 'Not a particularly interesting subject and too over processed for my liking.', '2009-04-20 21:09:30.000000', NULL, 1),
(5446057, 783910, 99140, '<td valign="top">Wow - before I even saw the title of the pic my first thought was CUJO!  Well pictured</td>', 'Wow - before I even saw the title of the pic my first thought was CUJO!  Well pictured', '2009-04-20 21:10:08.000000', NULL, 1),
(5446061, 783905, 101256, '<td valign="top">Well, it certainly is fearsome being dark and forbidding. Not particularly nightmare material, it is a very intriguing image.</td>', 'Well, it certainly is fearsome being dark and forbidding. Not particularly nightmare material, it is a very intriguing image.', '2009-04-20 21:11:21.000000', NULL, 1),
(5446062, 783932, 102315, '<td valign="top">Awesome capture and idea. Reminds me of Beetlejuice...Beetlejuice...Beetl.......</td>', 'Awesome capture and idea. Reminds me of Beetlejuice...Beetlejuice...Beetl.......', '2009-04-20 21:11:22.000000', NULL, 1),
(5446064, 781872, 102315, '<td valign="top">Love the technical''s of this one. I think the frogs are actually cute though.</td>', 'Love the technical''s of this one. I think the frogs are actually cute though.', '2009-04-20 21:12:25.000000', NULL, 1),
(5446065, 783647, 101256, '<td valign="top">Not particularly frightening, it is a great macro image. If the scale were a little bigger, it would certainly qualify as the stuff nightmares are made of.</td>', 'Not particularly frightening, it is a great macro image. If the scale were a little bigger, it would certainly qualify as the stuff nightmares are made of.', '2009-04-20 21:13:10.000000', NULL, 1),
(5446067, 782435, 102315, '<td valign="top">The lighting is way too harsh on the side of the building.</td>', 'The lighting is way too harsh on the side of the building.', '2009-04-20 21:13:41.000000', NULL, 1),
(5446068, 783943, 99140, '<td valign="top">Compelling subject - teeth are great but I kept losing focus with the leaves under the chin.</td>', 'Compelling subject - teeth are great but I kept losing focus with the leaves under the chin.', '2009-04-20 21:14:22.000000', NULL, 1),
(5446071, 783569, 102315, '<td valign="top">Spiff? Unfortunately is fits the challenge in my eyes seeing that your toy seems to be awaking from a nightmare. LOL</td>', 'Spiff? Unfortunately is fits the challenge in my eyes seeing that your toy seems to be awaking from a nightmare. LOL', '2009-04-20 21:15:22.000000', NULL, 1),
(5446074, 783820, 101256, '<td valign="top">Why the author would pick a very competant and beautiful black and white conversion rich in detail and a great demonstration of zone control as nightmare material is quite puzzling. If the image were foggy or vague in some way, perhaps. Point to the author for creating a great image - this reviewer doesn''t care that it isn''t particularly frighting or forbidding.</td>', 'Why the author would pick a very competant and beautiful black and white conversion rich in detail and a great demonstration of zone control as nightmare material is quite puzzling. If the image were foggy or vague in some way, perhaps. Point to the author for creating a great image - this reviewer doesn''t care that it isn''t particularly frighting or forbidding.', '2009-04-20 21:15:50.000000', NULL, 1),
(5446076, 783549, 102315, '<td valign="top">Was this taken at some sort of park with an action sequence to watch? Seems like a stretch for nightmare challenge though the capture is decent.</td>', 'Was this taken at some sort of park with an action sequence to watch? Seems like a stretch for nightmare challenge though the capture is decent.', '2009-04-20 21:16:31.000000', NULL, 1),
(5446079, 783242, 101256, '<td valign="top">The rather odd angle and intent is something that all claustrophobic viewers will greatly appreciate - or not appreciate. The stuff nightmares are made of.</td>', 'The rather odd angle and intent is something that all claustrophobic viewers will greatly appreciate - or not appreciate. The stuff nightmares are made of.', '2009-04-20 21:16:57.000000', NULL, 1),
(5446081, 783850, 99140, '<td valign="top">Nightmare for sure!  The bubbles help with knowing it is underwater - like that the blue background matches the eye color</td>', 'Nightmare for sure!  The bubbles help with knowing it is underwater - like that the blue background matches the eye color', '2009-04-20 21:17:25.000000', NULL, 1),
(5446082, 783965, 102315, '<td valign="top">Evil horse of death...really...this horse looks cute. Sorry but I think your reaching on this one.</td>', 'Evil horse of death...really...this horse looks cute. Sorry but I think your reaching on this one.', '2009-04-20 21:17:54.000000', NULL, 1),
(5446083, 783960, 99140, '<td valign="top">Good Capture</td>', 'Good Capture', '2009-04-20 21:17:58.000000', NULL, 1),
(5446085, 782942, 102315, '<td valign="top">Seems like too many random things happening in this photo. I don''t really know what to thing,</td>', 'Seems like too many random things happening in this photo. I don''t really know what to thing,', '2009-04-20 21:18:57.000000', NULL, 1),
(5446088, 783135, 99140, '<td valign="top">This picture is completely riveting and terrifying!  Very well done</td>', 'This picture is completely riveting and terrifying!  Very well done', '2009-04-20 21:19:53.000000', NULL, 1),
(5446092, 783745, 99140, '<td valign="top">Bit of a stretch for a nightmare challenge but who knows - this may scare the snot out of you!</td>', 'Bit of a stretch for a nightmare challenge but who knows - this may scare the snot out of you!', '2009-04-20 21:21:29.000000', NULL, 1),
(5446093, 783929, 99140, '<td valign="top">Eyes are fantastic - cats do pull of evil so well!</td>', 'Eyes are fantastic - cats do pull of evil so well!', '2009-04-20 21:22:15.000000', NULL, 1),
(5446096, 782868, 99140, '<td valign="top">Like the texture on the glass and that her fear still translates through it.</td>', 'Like the texture on the glass and that her fear still translates through it.', '2009-04-20 21:23:01.000000', NULL, 1),
(5446097, 783864, 102315, '<td valign="top">What a great portrait. Very sharp and nicely focused.</td>', 'What a great portrait. Very sharp and nicely focused.', '2009-04-20 21:23:08.000000', NULL, 1),
(5446098, 783933, 101256, '<td valign="top">Very gothic and effective, the zombie is a natural supernatural subject for this challenge. A terrific image in homage to many B level horror movies. Well done.</td>', 'Very gothic and effective, the zombie is a natural supernatural subject for this challenge. A terrific image in homage to many B level horror movies. Well done.', '2009-04-20 21:24:04.000000', NULL, 1),
(5446102, 783882, 101256, '<td valign="top">Here there be Zombies. Terrific conversion, strong and evocative of the natural terrors of the night. Well done.</td>', 'Here there be Zombies. Terrific conversion, strong and evocative of the natural terrors of the night. Well done.', '2009-04-20 21:24:59.000000', NULL, 1),
(5446103, 783935, 99140, '<td valign="top">If this was a street photography challenge I would have given a higher score but I find it slightly out of context for nightmare.  Still a great shot though.</td>', 'If this was a street photography challenge I would have given a higher score but I find it slightly out of context for nightmare.  Still a great shot though.', '2009-04-20 21:25:31.000000', NULL, 1),
(5446104, 783960, 101256, '<td valign="top">Yep - this is pretty frightening all right. Note to self: don''t review scary images of reptiles late at night before the dogs go outside for the final time.  Well done.</td>', 'Yep - this is pretty frightening all right. Note to self: don''t review scary images of reptiles late at night before the dogs go outside for the final time.  Well done.', '2009-04-20 21:26:01.000000', NULL, 1),
(5446109, 783845, 99140, '<td valign="top">I like the tilt and focus you used on this picture</td>', 'I like the tilt and focus you used on this picture', '2009-04-20 21:30:27.000000', NULL, 1),
(5446112, 783075, 101256, '<td valign="top">The result of a fevered dream or unnatural event - a provocative image which imparts a sense of fright and terror. Well done.</td>', 'The result of a fevered dream or unnatural event - a provocative image which imparts a sense of fright and terror. Well done.', '2009-04-20 21:32:38.000000', NULL, 1),
(5446113, 783565, 99140, '<td valign="top">Poor bunny - evil kitty!  Crisp pic</td>', 'Poor bunny - evil kitty!  Crisp pic', '2009-04-20 21:33:31.000000', NULL, 1),
(5446114, 782539, 101256, '<td valign="top">Very interesting use of a glass to impart an impression of sorrow. This image tells a story and it might not be a good one. Well done.</td>', 'Very interesting use of a glass to impart an impression of sorrow. This image tells a story and it might not be a good one. Well done.', '2009-04-20 21:33:47.000000', NULL, 1),
(5446115, 783864, 101256, '<td valign="top">A provocative image, it''s title invokes a sense of being outside the norm, but it''s not particularly frightening. As an image, it is spectacular - well thought out and impressive. A great image all by itself, it deserves some sort of recognition as an outstanding example of self expression. Well done.</td>', 'A provocative image, it''s title invokes a sense of being outside the norm, but it''s not particularly frightening. As an image, it is spectacular - well thought out and impressive. A great image all by itself, it deserves some sort of recognition as an outstanding example of self expression. Well done.', '2009-04-20 21:35:36.000000', NULL, 1),
(5446116, 783541, 101256, '<td valign="top">Sometimes it''s better to just shut up and vote when images are so perfect as to defy description.</td>', 'Sometimes it''s better to just shut up and vote when images are so perfect as to defy description.', '2009-04-20 21:36:15.000000', NULL, 1),
(5446121, 782942, 101256, '<td valign="top">Not particularly material for a nightmare as this image is more laugh out loud funny than scary. A good image, well detailed and hey, what the heck - a good job even if it missed that mark slightly.</td>', 'Not particularly material for a nightmare as this image is more laugh out loud funny than scary. A good image, well detailed and hey, what the heck - a good job even if it missed that mark slightly.', '2009-04-20 21:41:20.000000', NULL, 1),
(5446122, 783581, 101256, '<td valign="top">Could very well be a cheesy monster from a B scifi movie. It certainly would be scary if the lighting were turned down a little to create a darker effect. A worthy entry into the challenge.</td>', 'Could very well be a cheesy monster from a B scifi movie. It certainly would be scary if the lighting were turned down a little to create a darker effect. A worthy entry into the challenge.', '2009-04-20 21:42:38.000000', NULL, 1),
(5446123, 783394, 101256, '<td valign="top">Yep - this is quite nightmarish - a good concept, well lit and very effective with a A- creepy factor. Well done.</td>', 'Yep - this is quite nightmarish - a good concept, well lit and very effective with a A- creepy factor. Well done.', '2009-04-20 21:43:31.000000', NULL, 1),
(5446124, 783577, 101256, '<td valign="top">A perfect example of the stuff of nighmares does not require comment.</td>', 'A perfect example of the stuff of nighmares does not require comment.', '2009-04-20 21:43:51.000000', NULL, 1),
(5446126, 783907, 101256, '<td valign="top">Why a Holy Ghost of course he replied. Etheral and very effective if encountered in a dark alley in the dead of morning.</td>', 'Why a Holy Ghost of course he replied. Etheral and very effective if encountered in a dark alley in the dead of morning.', '2009-04-20 21:44:29.000000', NULL, 1),
(5446152, 782475, 101256, '<td valign="top">Sharks are both beautiful and terrifying predators which can be the stuff of nightmares. A convincing image with this wonderful creature. Good capture.</td>', 'Sharks are both beautiful and terrifying predators which can be the stuff of nightmares. A convincing image with this wonderful creature. Good capture.', '2009-04-20 22:04:57.000000', NULL, 1),
(5446153, 783816, 101256, '<td valign="top">Hannibal Lecter lives!! The only thing missing is fava beans. Well done.</td>', 'Hannibal Lecter lives!! The only thing missing is fava beans. Well done.', '2009-04-20 22:05:45.000000', NULL, 1),
(5446154, 783555, 86779, '<td valign="top">Not sure I understand?</td>', 'Not sure I understand?', '2009-04-20 22:05:46.000000', NULL, 1),
(5446156, 783576, 101256, '<td valign="top">Not sure what the author was trying to convey with this image, but it must have some kind of terrifying concept. Perhaps a little too subtle with the title and image.</td>', 'Not sure what the author was trying to convey with this image, but it must have some kind of terrifying concept. Perhaps a little too subtle with the title and image.', '2009-04-20 22:07:28.000000', NULL, 1),
(5446157, 783548, 101256, '<td valign="top">Very forbidding in a straight forward scifi kind of way. This could well be the Church of Razor Eddie - Punk God of the Straight Razor from the "Nightside" series.</td>', 'Very forbidding in a straight forward scifi kind of way. This could well be the Church of Razor Eddie - Punk God of the Straight Razor from the "Nightside" series.', '2009-04-20 22:08:45.000000', NULL, 1),
(5446160, 783950, 101256, '<td valign="top">Excellant - very provocative and ethereal in a not positive way. A "Twilight Zone" image if there ever was one. Well done.</td>', 'Excellant - very provocative and ethereal in a not positive way. A "Twilight Zone" image if there ever was one. Well done.', '2009-04-20 22:09:44.000000', NULL, 1),
(5446161, 783470, 101256, '<td valign="top">A classic horror meme properly lighted with red and offering a terrifying visage of the knife wielding maniac.</td>', 'A classic horror meme properly lighted with red and offering a terrifying visage of the knife wielding maniac.', '2009-04-20 22:10:35.000000', NULL, 1),
(5446162, 783816, 86779, '<td valign="top">Ooh 9!</td>', 'Ooh 9!', '2009-04-20 22:11:10.000000', NULL, 1),
(5446163, 783931, 101256, '<td valign="top">Yes indeed - something that no parent ever wants to have happen. Very terrifying prospect.</td>', 'Yes indeed - something that no parent ever wants to have happen. Very terrifying prospect.', '2009-04-20 22:11:14.000000', NULL, 1),
(5446165, 783933, 86779, '<td valign="top">Awesome, my 10!</td>', 'Awesome, my 10!', '2009-04-20 22:13:32.000000', NULL, 1),
(5446167, 783549, 86779, '<td valign="top">Great capture, how on earth did you get this?</td>', 'Great capture, how on earth did you get this?', '2009-04-20 22:14:19.000000', NULL, 1),
(5446172, 783420, 101256, '<td valign="top">A curiosity and something that could well be seen in a horror movie or perhaps a wierd "Dr. Who" story like "Blink". Well done.</td>', 'A curiosity and something that could well be seen in a horror movie or perhaps a wierd "Dr. Who" story like "Blink". Well done.', '2009-04-20 22:16:00.000000', NULL, 1),
(5446173, 783956, 101256, '<td valign="top">Another parent''s nightmare and one that is more provocative than seen previously. A frightening prospect and one every parent fears.</td>', 'Another parent''s nightmare and one that is more provocative than seen previously. A frightening prospect and one every parent fears.', '2009-04-20 22:16:51.000000', NULL, 1),
(5446177, 783079, 101256, '<td valign="top">Ok...so the author is afraid of...the sky? Agoraphobia? Pyrophobia? The intent is unknown, thus not terribly effective as a nightmare.</td>', 'Ok...so the author is afraid of...the sky? Agoraphobia? Pyrophobia? The intent is unknown, thus not terribly effective as a nightmare.', '2009-04-20 22:19:00.000000', NULL, 1),
(5446179, 783594, 101256, '<td valign="top">A wonderful meme using fear of high tech world war - carefully constructed, lit and posed, this is a wonderfully terrifying image of potential human extermination. Well done.</td>', 'A wonderful meme using fear of high tech world war - carefully constructed, lit and posed, this is a wonderfully terrifying image of potential human extermination. Well done.', '2009-04-20 22:20:12.000000', NULL, 1),
(5446184, 783758, 101256, '<td valign="top">While over done with the dark, the image evokes a image of powerful lords terrorising the peasantry.</td>', 'While over done with the dark, the image evokes a image of powerful lords terrorising the peasantry.', '2009-04-20 22:22:01.000000', NULL, 1),
(5446185, 783914, 101256, '<td valign="top">A very interesting view of how terror can be different things to different people. A good effective nightmare image.</td>', 'A very interesting view of how terror can be different things to different people. A good effective nightmare image.', '2009-04-20 22:23:25.000000', NULL, 1),
(5446186, 783470, 86779, '<td valign="top">Nice lighting! 9</td>', 'Nice lighting! 9', '2009-04-20 22:23:27.000000', NULL, 1),
(5446187, 783942, 101256, '<td valign="top">Laugh out loud funny and so very true. Well done.</td>', 'Laugh out loud funny and so very true. Well done.', '2009-04-20 22:23:47.000000', NULL, 1),
(5446188, 783411, 101256, '<td valign="top">Sex and violence - straight out of Quintin Tarentino. Well done.</td>', 'Sex and violence - straight out of Quintin Tarentino. Well done.', '2009-04-20 22:24:14.000000', NULL, 1),
(5446192, 782868, 101256, '<td valign="top">For the claustrophobe, this can be a terrifying prospect. Very well composed and captured. The model is suitably effective. Well done.</td>', 'For the claustrophobe, this can be a terrifying prospect. Very well composed and captured. The model is suitably effective. Well done.', '2009-04-20 22:25:06.000000', NULL, 1),
(5446193, 782618, 86779, '<td valign="top">Ha ha, what a shoehorn! :P</td>', 'Ha ha, what a shoehorn! :P', '2009-04-20 22:25:42.000000', NULL, 1),
(5446195, 783920, 101256, '<td valign="top">Very effective use of lighting, crisp and sharp and properly titled. A classic horror or movie fright meme. Well done.</td>', 'Very effective use of lighting, crisp and sharp and properly titled. A classic horror or movie fright meme. Well done.', '2009-04-20 22:26:03.000000', NULL, 1),
(5446196, 783951, 86779, '<td valign="top">Abstract, I love it! 8</td>', 'Abstract, I love it! 8', '2009-04-20 22:26:07.000000', NULL, 1),
