(5447056, 783931, 96751, '<td valign="top">An excellent case where the title makes the shot.</td>', 'An excellent case where the title makes the shot.', '2009-04-21 14:08:44.000000', NULL, 1),
(5447057, 783951, 96751, '<td valign="top">Very creative. Love the work you put into this.  But I feel the lighting is fighting the image, overblown.</td>', 'Very creative. Love the work you put into this.  But I feel the lighting is fighting the image, overblown.', '2009-04-21 14:11:15.000000', NULL, 1),
(5447059, 782942, 60698, '<td valign="top">Good nightmarish quality... nothing makes sense in nightmares. It also made me laugh so maybe you were also going for that too! Very unique! Excellent!</td>', 'Good nightmarish quality... nothing makes sense in nightmares. It also made me laugh so maybe you were also going for that too! Very unique! Excellent!', '2009-04-21 14:11:36.000000', NULL, 1),
(5447061, 782258, 60698, '<td valign="top">Nicely portrayed! Great warm tones and isolation.</td>', 'Nicely portrayed! Great warm tones and isolation.', '2009-04-21 14:13:45.000000', NULL, 1),
(5447062, 783606, 96751, '<td valign="top">This is a definite nightmare.  The idea is good, but the treatment leaves me indifferent.  I don''t know if it''s the lack of color, or that the subject is so far away.  I don''t think the border helps.</td>', 'This is a definite nightmare.  The idea is good, but the treatment leaves me indifferent.  I don''t know if it''s the lack of color, or that the subject is so far away.  I don''t think the border helps.', '2009-04-21 14:14:17.000000', NULL, 1),
(5447064, 781977, 96751, '<td valign="top">I don''t get the concept.  But the lighting and detail and tone are great.</td>', 'I don''t get the concept.  But the lighting and detail and tone are great.', '2009-04-21 14:14:51.000000', NULL, 1),
(5447065, 783920, 96751, '<td valign="top">Yup, bugs = nightmare.</td>', 'Yup, bugs = nightmare.', '2009-04-21 14:15:07.000000', NULL, 1),
(5447067, 783864, 96751, '<td valign="top">Great treatment.  Incredible detail.</td>', 'Great treatment.  Incredible detail.', '2009-04-21 14:16:04.000000', NULL, 1),
